// CBSE 12 Mathematics ch07 Integrals — practice bank with independent re-solve checks: every
// antiderivative is differentiated numerically and compared with the integrand at sample points,
// every definite integral is recomputed with Simpson's rule, every partial-fraction split is
// evaluated on both sides. The definite integral as the limit of a sum (deleted) appears nowhere.
import { Q, caseQ, child, mk } from '../../cbse-12-mathematics-ch01/src/lib.mjs';
import { isAnti, simpson, near, same, ln, R6 } from './calc.mjs';

const P = Math.PI;
/** String.raw, but a literal backslash-n backslash-n (paragraph break) becomes a real blank line. */
const r = (s, ...v) => String.raw(s, ...v).replace(/\\n\\n/g, '\n\n');
const { sin, cos, tan, exp, sqrt, atan, asin, abs } = Math;
const sec = (x) => 1 / cos(x);
/** Antiderivative options: exactly one differentiates back to g, and it is the key. */
const anti = (C, Fs, g, xs) => C.which(Fs.map((F) => isAnti(F, g, xs)), true);
const X1 = [0.4, 1.1, 2.3]; // generic sample points (x > 0)

// =============================================================== MCQ
Q('m01', mk.mcq({ stem: r`$\displaystyle\int x^5\,dx$ equals`, opts: [r`$\dfrac{x^6}{6} + C$`, r`$5x^4 + C$`, r`$x^6 + C$`, r`$\dfrac{x^4}{4} + C$`], key: 'a', sol: r`Power rule: $\displaystyle\int x^n\,dx = \dfrac{x^{n+1}}{n+1} + C$ with $n = 5$. Option (b) is the derivative, not the integral.`, d: 1, c: 'recall', t: [1], time: 30 }),
  (C) => anti(C, [(x) => x ** 6 / 6, (x) => 5 * x ** 4, (x) => x ** 6, (x) => x ** 4 / 4], (x) => x ** 5, X1));
Q('m02', mk.mcq({ stem: r`For $x > 0$, an antiderivative family of $\dfrac{3}{x} + 2e^x$ is`, opts: [r`$3\log|x| + 2e^x + C$`, r`$-\dfrac{3}{x^2} + 2e^x + C$`, r`$3\log|x| + 2xe^x + C$`, r`$\dfrac{3}{x^2} + 2e^x + C$`], key: 'a', sol: r`$\displaystyle\int \dfrac1x\,dx = \log|x|$ and $\displaystyle\int e^x\,dx = e^x$, so the answer is $3\log|x| + 2e^x + C$. Option (b) differentiates $\dfrac3x$ instead of integrating it.`, d: 2, c: 'understanding', t: [1], time: 45 }),
  (C) => anti(C, [(x) => 3 * ln(abs(x)) + 2 * exp(x), (x) => -3 / x ** 2 + 2 * exp(x), (x) => 3 * ln(abs(x)) + 2 * x * exp(x), (x) => 3 / x ** 2 + 2 * exp(x)], (x) => 3 / x + 2 * exp(x), X1));
Q('m03', mk.mcq({ stem: r`$\displaystyle\int \sec x\,(\sec x + \tan x)\,dx$ is`, opts: [r`$\tan x + \sec x + C$`, r`$\sec x\tan x + \sec^2 x + C$`, r`$\tan x - \sec x + C$`, r`$\sec x + C$`], key: 'a', sol: r`Expand: $\sec^2 x + \sec x\tan x$. These are the derivatives of $\tan x$ and $\sec x$, so the integral is $\tan x + \sec x + C$. Option (b) only rewrites the integrand.`, d: 2, c: 'understanding', t: [1], time: 60 }),
  (C) => anti(C, [(x) => tan(x) + sec(x), (x) => sec(x) * tan(x) + sec(x) ** 2, (x) => tan(x) - sec(x), (x) => sec(x)], (x) => sec(x) * (sec(x) + tan(x)), [0.2, 0.5, 1.0]));
Q('m04', mk.mcq({ stem: r`If $F'(x) = 4x^3 - 6x$ and $F(1) = 3$, then $F(x)$ is`, opts: [r`$x^4 - 3x^2 + 5$`, r`$x^4 - 3x^2 + 3$`, r`$x^4 - 3x^2 + 1$`, r`$12x^2 - 9$`], key: 'a', sol: r`$F(x) = x^4 - 3x^2 + C$. Then $F(1) = 1 - 3 + C = 3$ gives $C = 5$. Option (d) has the right value at $x = 1$ but is not an antiderivative of $F'$.`, d: 2, c: 'application', t: [1], time: 60 }),
  (C) => { const Fs = [(x) => x ** 4 - 3 * x * x + 5, (x) => x ** 4 - 3 * x * x + 3, (x) => x ** 4 - 3 * x * x + 1, (x) => 12 * x * x - 9]; C.which(Fs.map((F) => isAnti(F, (x) => 4 * x ** 3 - 6 * x, X1) && near(F(1), 3)), true); });
Q('m05', mk.mcq({ stem: r`Using a substitution, $\displaystyle\int \dfrac{2x}{x^2 + 5}\,dx$ equals`, opts: [r`$\log(x^2 + 5) + C$`, r`$\dfrac{1}{x^2 + 5} + C$`, r`$2\log(x^2 + 5) + C$`, r`$x^2\log(x^2 + 5) + C$`], key: 'a', sol: r`Put $t = x^2 + 5$, $dt = 2x\,dx$: the integral is $\displaystyle\int \dfrac{dt}{t} = \log|t| + C = \log(x^2 + 5) + C$ (no modulus needed, since $x^2 + 5 > 0$).`, d: 2, c: 'understanding', t: [2], time: 60 }),
  (C) => anti(C, [(x) => ln(x * x + 5), (x) => 1 / (x * x + 5), (x) => 2 * ln(x * x + 5), (x) => x * x * ln(x * x + 5)], (x) => (2 * x) / (x * x + 5), [-1.3, 0.4, 2.2]));
Q('m06', mk.mcq({ stem: r`$\displaystyle\int \cos x\; e^{\sin x}\,dx$ is`, opts: [r`$e^{\sin x} + C$`, r`$e^{\cos x} + C$`, r`$\sin x\; e^{\sin x} + C$`, r`$-e^{\sin x} + C$`], key: 'a', sol: r`With $t = \sin x$, $dt = \cos x\,dx$, the integral becomes $\displaystyle\int e^t\,dt = e^t + C = e^{\sin x} + C$.`, d: 2, c: 'understanding', t: [2], time: 60 }),
  (C) => anti(C, [(x) => exp(sin(x)), (x) => exp(cos(x)), (x) => sin(x) * exp(sin(x)), (x) => -exp(sin(x))], (x) => cos(x) * exp(sin(x)), [0.3, 1.2, 2.5]));
Q('m07', mk.mcq({ stem: r`On an interval where $\cos x > 0$, $\displaystyle\int \tan x\,dx$ is`, opts: [r`$\log|\sec x| + C$`, r`$\log|\cos x| + C$`, r`$\sec^2 x + C$`, r`$-\log|\sec x| + C$`], key: 'a', sol: r`$\tan x = \dfrac{\sin x}{\cos x}$; put $t = \cos x$, $dt = -\sin x\,dx$: $-\log|\cos x| + C = \log|\sec x| + C$. Option (b) has the wrong sign.`, d: 2, c: 'understanding', t: [2], time: 60 }),
  (C) => anti(C, [(x) => ln(abs(sec(x))), (x) => ln(abs(cos(x))), (x) => sec(x) ** 2, (x) => -ln(abs(sec(x)))], tan, [0.3, 0.8, 1.2]));
Q('m08', mk.mcq({ stem: r`For $x > 1$, $\displaystyle\int \dfrac{(\log x)^2}{x}\,dx$ is`, opts: [r`$\dfrac{(\log x)^3}{3} + C$`, r`$\dfrac{2\log x}{x} + C$`, r`$(\log x)^3 + C$`, r`$\dfrac{(\log x)^2}{2} + C$`], key: 'a', sol: r`Put $t = \log x$, so $dt = \dfrac{dx}{x}$: $\displaystyle\int t^2\,dt = \dfrac{t^3}{3} + C$.`, d: 3, c: 'application', t: [2], time: 75 }),
  (C) => anti(C, [(x) => ln(x) ** 3 / 3, (x) => (2 * ln(x)) / x, (x) => ln(x) ** 3, (x) => ln(x) ** 2 / 2], (x) => ln(x) ** 2 / x, [1.5, 2.5, 4]));
Q('m09', mk.mcq({ stem: r`$\displaystyle\int \dfrac{dx}{x^2 + 16}$ equals`, opts: [r`$\dfrac14\tan^{-1}\dfrac{x}{4} + C$`, r`$\tan^{-1}\dfrac{x}{4} + C$`, r`$\dfrac18\log\left|\dfrac{x - 4}{x + 4}\right| + C$`, r`$\dfrac{1}{16}\tan^{-1}\dfrac{x}{16} + C$`], key: 'a', sol: r`Standard form $\displaystyle\int \dfrac{dx}{x^2 + a^2} = \dfrac1a\tan^{-1}\dfrac xa + C$ with $a = 4$. Option (c) is the form for $x^2 - a^2$.`, d: 2, c: 'recall', t: [3], time: 45 }),
  (C) => anti(C, [(x) => atan(x / 4) / 4, (x) => atan(x / 4), (x) => ln(abs((x - 4) / (x + 4))) / 8, (x) => atan(x / 16) / 16], (x) => 1 / (x * x + 16), [-2, 0.5, 3]));
Q('m10', mk.mcq({ stem: r`For $-3 < x < 3$, $\displaystyle\int \dfrac{dx}{\sqrt{9 - x^2}}$ is`, opts: [r`$\sin^{-1}\dfrac{x}{3} + C$`, r`$\dfrac13\sin^{-1}\dfrac{x}{3} + C$`, r`$\sin^{-1}\dfrac{x}{9} + C$`, r`$\cos^{-1}\dfrac{x}{3} + C$`], key: 'a', sol: r`$\displaystyle\int \dfrac{dx}{\sqrt{a^2 - x^2}} = \sin^{-1}\dfrac xa + C$ with $a = 3$. Option (d) differentiates to $-\dfrac{1}{\sqrt{9 - x^2}}$.`, d: 2, c: 'understanding', t: [3], time: 45 }),
  (C) => anti(C, [(x) => asin(x / 3), (x) => asin(x / 3) / 3, (x) => asin(x / 9), (x) => Math.acos(x / 3)], (x) => 1 / sqrt(9 - x * x), [-1.7, 0.3, 2.2]));
Q('m11', mk.mcq({ stem: r`After completing the square, $\displaystyle\int \dfrac{dx}{x^2 + 6x + 13}$ is found to be`, opts: [r`$\dfrac12\tan^{-1}\dfrac{x + 3}{2} + C$`, r`$\tan^{-1}\dfrac{x + 3}{2} + C$`, r`$\dfrac12\tan^{-1}\dfrac{x - 3}{2} + C$`, r`$\dfrac14\tan^{-1}\dfrac{x + 3}{4} + C$`], key: 'a', sol: r`$x^2 + 6x + 13 = (x + 3)^2 + 2^2$, so the integral is $\dfrac12\tan^{-1}\dfrac{x + 3}{2} + C$. Option (c) shifts the wrong way.`, d: 3, c: 'application', t: [3], time: 75 }),
  (C) => anti(C, [(x) => atan((x + 3) / 2) / 2, (x) => atan((x + 3) / 2), (x) => atan((x - 3) / 2) / 2, (x) => atan((x + 3) / 4) / 4], (x) => 1 / (x * x + 6 * x + 13), [-4, -1, 1.5]));
Q('m12', mk.mcq({ stem: r`$\displaystyle\int \dfrac{dx}{x^2 - 25}$ is`, opts: [r`$\dfrac{1}{10}\log\left|\dfrac{x - 5}{x + 5}\right| + C$`, r`$\dfrac{1}{10}\log\left|\dfrac{x + 5}{x - 5}\right| + C$`, r`$\dfrac{1}{5}\log\left|\dfrac{x - 5}{x + 5}\right| + C$`, r`$\log|x^2 - 25| + C$`], key: 'a', sol: r`$\displaystyle\int \dfrac{dx}{x^2 - a^2} = \dfrac{1}{2a}\log\left|\dfrac{x - a}{x + a}\right| + C$ with $a = 5$, so the factor is $\dfrac{1}{10}$. Option (b) has the fraction upside down, which flips the sign.`, d: 2, c: 'understanding', t: [3], time: 60 }),
  (C) => anti(C, [(x) => ln(abs((x - 5) / (x + 5))) / 10, (x) => ln(abs((x + 5) / (x - 5))) / 10, (x) => ln(abs((x - 5) / (x + 5))) / 5, (x) => ln(abs(x * x - 25))], (x) => 1 / (x * x - 25), [1, 2.5, 6, 8]));
Q('m13', mk.mcq({ stem: r`If $\dfrac{5x + 1}{(x - 1)(x + 2)} = \dfrac{A}{x - 1} + \dfrac{B}{x + 2}$, then`, opts: [r`$A = 2,\ B = 3$`, r`$A = 3,\ B = 2$`, r`$A = 2,\ B = -3$`, r`$A = -2,\ B = 3$`], key: 'a', sol: r`$5x + 1 = A(x + 2) + B(x - 1)$. Put $x = 1$: $6 = 3A$, $A = 2$. Put $x = -2$: $-9 = -3B$, $B = 3$.`, d: 2, c: 'understanding', t: [4], time: 60 }),
  (C) => { const A = (5 * 1 + 1) / (1 + 2), B = (5 * -2 + 1) / (-2 - 1); C.assert(same((x) => (5 * x + 1) / ((x - 1) * (x + 2)), (x) => A / (x - 1) + B / (x + 2), [0, 3, 5.5]), 'split'); C.which([[2, 3], [3, 2], [2, -3], [-2, 3]], [A, B]); });
Q('m14', mk.mcq({ stem: r`By partial fractions, $\displaystyle\int \dfrac{dx}{x(x + 1)}$ equals`, opts: [r`$\log\left|\dfrac{x}{x + 1}\right| + C$`, r`$\log|x(x + 1)| + C$`, r`$\log\left|\dfrac{x + 1}{x}\right| + C$`, r`$\log|x| \cdot \log|x + 1| + C$`], key: 'a', sol: r`$\dfrac{1}{x(x + 1)} = \dfrac1x - \dfrac{1}{x + 1}$, so the integral is $\log|x| - \log|x + 1| + C$, which is option (a).`, d: 3, c: 'application', t: [4], time: 75 }),
  (C) => anti(C, [(x) => ln(abs(x / (x + 1))), (x) => ln(abs(x * (x + 1))), (x) => ln(abs((x + 1) / x)), (x) => ln(abs(x)) * ln(abs(x + 1))], (x) => 1 / (x * (x + 1)), [0.5, 1.7, 3]));
Q('m15', mk.mcq({ stem: r`Integrating by parts, $\displaystyle\int x e^x\,dx$ is`, opts: [r`$(x - 1)e^x + C$`, r`$(x + 1)e^x + C$`, r`$xe^x + C$`, r`$\dfrac{x^2}{2}e^x + C$`], key: 'a', sol: r`Take $u = x$, $dv = e^x\,dx$: $xe^x - \displaystyle\int e^x\,dx = xe^x - e^x + C$.`, d: 2, c: 'understanding', t: [5], time: 60 }),
  (C) => anti(C, [(x) => (x - 1) * exp(x), (x) => (x + 1) * exp(x), (x) => x * exp(x), (x) => (x * x * exp(x)) / 2], (x) => x * exp(x), X1));
Q('m16', mk.mcq({ stem: r`$\displaystyle\int e^x(\sin x + \cos x)\,dx$ is`, opts: [r`$e^x\sin x + C$`, r`$e^x\cos x + C$`, r`$e^x(\sin x - \cos x) + C$`, r`$-e^x\cos x + C$`], key: 'a', sol: r`The bracket is $f(x) + f'(x)$ with $f(x) = \sin x$, and $\displaystyle\int e^x[f(x) + f'(x)]\,dx = e^xf(x) + C$.`, d: 3, c: 'application', t: [5], time: 60 }),
  (C) => anti(C, [(x) => exp(x) * sin(x), (x) => exp(x) * cos(x), (x) => exp(x) * (sin(x) - cos(x)), (x) => -exp(x) * cos(x)], (x) => exp(x) * (sin(x) + cos(x)), X1));
Q('m17', mk.mcq({ stem: r`$\displaystyle\int_0^2 (3x^2 + 1)\,dx$ equals`, opts: ['$10$', '$8$', '$12$', '$14$'], key: 'a', sol: r`$\left[x^3 + x\right]_0^2 = (8 + 2) - 0 = 10$.`, d: 1, c: 'understanding', t: [6], time: 45 }),
  (C) => C.which([10, 8, 12, 14], R6(simpson((x) => 3 * x * x + 1, 0, 2))));
Q('m18', mk.mcq({ stem: r`$\displaystyle\int_{-2}^{2} x^3\cos x\,dx$ equals`, opts: ['$0$', r`$2\cos 2$`, '$8$', r`$16\sin 2$`], key: 'a', sol: r`$f(x) = x^3\cos x$ satisfies $f(-x) = -f(x)$ (odd), so its integral over $[-2, 2]$ is $0$.`, d: 3, c: 'application', t: [6], time: 60 }),
  (C) => C.which([0, 2 * cos(2), 8, 16 * sin(2)].map(R6), R6(simpson((x) => x ** 3 * cos(x), -2, 2))));
Q('m19', mk.mcq({ stem: r`$\displaystyle\int_0^{\pi/2} \dfrac{\sin^5 x}{\sin^5 x + \cos^5 x}\,dx$ equals`, opts: [r`$\dfrac{\pi}{4}$`, r`$\dfrac{\pi}{2}$`, '$0$', '$1$'], key: 'a', sol: r`Call it $I$. Replacing $x$ by $\dfrac{\pi}{2} - x$ swaps $\sin$ and $\cos$, so $I$ also equals the integral of $\dfrac{\cos^5 x}{\sin^5 x + \cos^5 x}$. Adding, $2I = \displaystyle\int_0^{\pi/2} 1\,dx = \dfrac{\pi}{2}$, so $I = \dfrac{\pi}{4}$.`, d: 3, c: 'analysis', t: [6], time: 90 }),
  (C) => C.which([P / 4, P / 2, 0, 1].map(R6), R6(simpson((x) => sin(x) ** 5 / (sin(x) ** 5 + cos(x) ** 5), 0, P / 2))));
Q('m20', mk.mcq({ stem: r`For $x > 0$, $\displaystyle\int \log x\,dx$ is`, opts: [r`$x\log x - x + C$`, r`$x\log x + x + C$`, r`$\dfrac1x + C$`, r`$\dfrac{(\log x)^2}{2} + C$`], key: 'a', sol: r`Write $\log x = 1 \cdot \log x$ and take $u = \log x$, $dv = dx$: $x\log x - \displaystyle\int x \cdot \dfrac1x\,dx = x\log x - x + C$.`, d: 2, c: 'understanding', t: [5], time: 60 }),
  (C) => anti(C, [(x) => x * ln(x) - x, (x) => x * ln(x) + x, (x) => 1 / x, (x) => ln(x) ** 2 / 2], ln, [0.5, 2, 5]));

// =============================================================== assertion-reason (keys a b c d a b)
Q('ar1', mk.ar({ a: r`$\displaystyle\int e^{3x}\,dx = \dfrac{e^{3x}}{3} + C$.`, r: r`$\dfrac{d}{dx}\left(\dfrac{e^{3x}}{3}\right) = e^{3x}$.`, key: 'a', sol: r`R is true by the chain rule. Integration reverses differentiation, so R is exactly why A holds.`, d: 1, c: 'understanding', t: [1] }),
  (C) => { C.assert(isAnti((x) => exp(3 * x) / 3, (x) => exp(3 * x), X1), 'A true'); C.key('a'); });
Q('ar2', mk.ar({ a: r`On $(0, \pi)$, $\displaystyle\int \cot x\,dx = \log|\sin x| + C$.`, r: r`The function $\cot x$ is not defined at $x = 0$.`, key: 'b', sol: r`A: put $t = \sin x$; $\dfrac{\cos x}{\sin x}\,dx = \dfrac{dt}{t}$, giving $\log|\sin x|$. R is true, but where $\cot x$ is undefined has nothing to do with the value of the integral on $(0, \pi)$.`, d: 2, c: 'understanding', t: [2] }),
  (C) => { C.assert(isAnti((x) => ln(abs(sin(x))), (x) => 1 / tan(x), [0.4, 1, 2.5]), 'A true'); C.assert(!Number.isFinite(cos(0) / sin(0)), 'R true'); C.key('b'); });
Q('ar3', mk.ar({ a: r`$\displaystyle\int_{-1}^{1} |x|\,dx = 1$.`, r: r`If $f$ is even, then $\displaystyle\int_{-a}^{a} f(x)\,dx = 0$.`, key: 'c', sol: r`A: $|x|$ is even, so the integral is $2\displaystyle\int_0^1 x\,dx = 1$; A is true. R is false: for an even function the integral over $[-a, a]$ is **twice** the integral over $[0, a]$; it is odd functions that give $0$.`, d: 2, c: 'understanding', t: [6] }),
  (C) => { C.assert(near(simpson(abs, -1, 1, 20000), 1), 'A = 1'); C.assert(!near(simpson((x) => x * x, -1, 1), 0), 'R fails for x^2'); C.key('c'); });
Q('ar4', mk.ar({ a: r`$\displaystyle\int \dfrac{dx}{\sqrt{x^2 + 4}} = \sin^{-1}\dfrac{x}{2} + C$.`, r: r`$\displaystyle\int \dfrac{dx}{\sqrt{a^2 - x^2}} = \sin^{-1}\dfrac{x}{a} + C$.`, key: 'd', sol: r`R is the standard result for $\sqrt{a^2 - x^2}$. The integrand in A has $\sqrt{x^2 + a^2}$, whose integral is $\log\left|x + \sqrt{x^2 + 4}\right| + C$, so A is false.`, d: 3, c: 'analysis', t: [3] }),
  (C) => { const g = (x) => 1 / sqrt(x * x + 4); C.assert(!isAnti((x) => asin(x / 2), g, [0.3, 1.1]) && isAnti((x) => ln(abs(x + sqrt(x * x + 4))), g, [0.3, 1.1, 3]), 'A false'); C.assert(isAnti((x) => asin(x / 3), (x) => 1 / sqrt(9 - x * x), [0.5, 2]), 'R true'); C.key('d'); });
Q('ar5', mk.ar({ a: r`For $x > 0$, $\displaystyle\int e^x\left(\dfrac1x - \dfrac{1}{x^2}\right)dx = \dfrac{e^x}{x} + C$.`, r: r`$\displaystyle\int e^x\,[f(x) + f'(x)]\,dx = e^x f(x) + C$.`, key: 'a', sol: r`With $f(x) = \dfrac1x$, $f'(x) = -\dfrac{1}{x^2}$, so the bracket is $f + f'$ and R gives A directly.`, d: 3, c: 'application', t: [5] }),
  (C) => { C.assert(isAnti((x) => exp(x) / x, (x) => exp(x) * (1 / x - 1 / (x * x)), [0.5, 1.5, 3]), 'A true'); C.key('a'); });
Q('ar6', mk.ar({ a: r`$\displaystyle\int \dfrac{x^2 + 1}{x^2 - 1}\,dx = x + \log\left|\dfrac{x - 1}{x + 1}\right| + C$.`, r: 'A rational function whose numerator has a lower degree than its denominator is called a proper rational function.', key: 'b', sol: r`A: divide first, $\dfrac{x^2 + 1}{x^2 - 1} = 1 + \dfrac{2}{x^2 - 1}$, and $\displaystyle\int \dfrac{2\,dx}{x^2 - 1} = \log\left|\dfrac{x - 1}{x + 1}\right|$; A is true. R is a correct definition, but A's integrand is improper, so the definition does not explain A.`, d: 3, c: 'analysis', t: [4] }),
  (C) => { C.assert(isAnti((x) => x + ln(abs((x - 1) / (x + 1))), (x) => (x * x + 1) / (x * x - 1), [0.5, 2, 3]), 'A true'); C.key('b'); });

// =============================================================== true-false
Q('tf1', mk.tf({ stem: 'True or false: two antiderivatives of the same function on an interval differ by a constant.', key: 't', sol: r`True. If $F' = G' = f$, then $(F - G)' = 0$ on the interval, so $F - G$ is constant there.`, d: 1, c: 'recall', t: [1] }),
  (C) => { const F = (x) => x * x + 3, G = (x) => x * x - 7; C.assert(isAnti(F, (x) => 2 * x, X1) && isAnti(G, (x) => 2 * x, X1) && [0.4, 1.3, 5].every((x) => near(F(x) - G(x), 10)), 'differ by 10'); C.key('t'); });
Q('tf2', mk.tf({ stem: r`True or false: $\displaystyle\int \sin 2x\,dx = -\cos 2x + C$.`, key: 'f', sol: r`False. Differentiating $-\cos 2x$ gives $2\sin 2x$. The correct result is $-\dfrac12\cos 2x + C$.`, d: 2, c: 'understanding', t: [2] }),
  (C) => { C.assert(!isAnti((x) => -cos(2 * x), (x) => sin(2 * x), X1) && isAnti((x) => -cos(2 * x) / 2, (x) => sin(2 * x), X1), 'needs 1/2'); C.key('f'); });
Q('tf3', mk.tf({ stem: r`True or false: the integral of a product is the product of the integrals, that is, $\displaystyle\int f(x)g(x)\,dx = \int f(x)\,dx \cdot \int g(x)\,dx$.`, key: 'f', sol: r`False. Take $f(x) = g(x) = x$: the left side is $\dfrac{x^3}{3} + C$, but the product of the integrals is $\dfrac{x^4}{4}$ plus constants. Products need integration by parts.`, d: 2, c: 'understanding', t: [5] }),
  (C) => { C.assert(!isAnti((x) => x ** 4 / 4, (x) => x * x, X1), 'counterexample'); C.key('f'); });
Q('tf4', mk.tf({ stem: r`True or false: for a function continuous on $[a, b]$, $\displaystyle\int_a^b f(x)\,dx = -\int_b^a f(x)\,dx$.`, key: 't', sol: r`True. With $F' = f$, the left side is $F(b) - F(a)$ and the right side is $-(F(a) - F(b))$, the same number.`, d: 1, c: 'recall', t: [6] }),
  (C) => { const g = (x) => x * x + sin(x); C.assert(near(simpson(g, 1, 3), -simpson(g, 3, 1)), 'reversal'); C.key('t'); });
Q('tf5', mk.tf({ stem: r`True or false: $\displaystyle\int_0^{\pi} \cos^3 x\,dx = 0$.`, key: 't', sol: r`True. $\cos^3(\pi - x) = -\cos^3 x$, so with $\displaystyle\int_0^a f(x)\,dx = \int_0^a f(a - x)\,dx$ the integral equals its own negative, hence $0$.`, d: 3, c: 'application', t: [6] }),
  (C) => { C.assert(near(simpson((x) => cos(x) ** 3, 0, P), 0, 1e-9), 'zero'); C.key('t'); });

// =============================================================== fill in the blank
Q('fb1', mk.fill({ stem: r`$\displaystyle\int \dfrac{1}{x}\,dx = $ ____ $+ C$ (for $x \ne 0$).`, acc: [['log|x|', r`$\log|x|$`, 'ln|x|', r`$\ln|x|$`]], sol: r`The derivative of $\log|x|$ is $\dfrac1x$ for both positive and negative $x$, hence the modulus.`, d: 1, c: 'recall', t: [1] }),
  (C) => { C.assert(isAnti((x) => ln(abs(x)), (x) => 1 / x, [-2, -0.5, 0.7, 3]), 'log|x| on both sides of 0'); C.blank('log|x|'); });
Q('fb2', mk.fill({ stem: r`$\displaystyle\int_1^e \dfrac{1}{x}\,dx = $ ____.`, acc: [['1']], sol: r`$\left[\log x\right]_1^e = 1 - 0 = 1$.`, d: 1, c: 'understanding', t: [6] }),
  (C) => C.blank(R6(simpson((x) => 1 / x, 1, Math.E))));
Q('fb3', mk.fill({ stem: r`If $\displaystyle\int e^{5x}\,dx = k\,e^{5x} + C$, then $k = $ ____.`, acc: [['1/5', '0.2']], sol: r`The derivative of $e^{5x}$ is $5e^{5x}$, so we need $k = 1/5$, that is, $0.2$.`, d: 2, c: 'understanding', t: [2] }),
  (C) => { const k = 1 / 5; C.assert(isAnti((x) => k * exp(5 * x), (x) => exp(5 * x), [0.1, 0.4]), 'k = 1/5'); C.blank(k); });
Q('fb4', mk.fill({ stem: r`$\displaystyle\int \dfrac{dx}{x^2 + 49} = \dfrac{1}{k}\tan^{-1}\dfrac{x}{7} + C$, where $k = $ ____.`, acc: [['7']], sol: r`Compare with $\dfrac1a\tan^{-1}\dfrac xa$, $a = 7$.`, d: 2, c: 'recall', t: [3] }),
  (C) => { const k = 7; C.assert(isAnti((x) => atan(x / 7) / k, (x) => 1 / (x * x + 49), [-3, 1, 5]), 'k = 7'); C.blank(k); });
Q('fb5', mk.fill({ stem: r`If $\displaystyle\int_0^a 2x\,dx = 25$ and $a > 0$, then $a = $ ____.`, acc: [['5']], sol: r`$\left[x^2\right]_0^a = a^2 = 25$, and $a > 0$ gives $a = 5$.`, d: 2, c: 'application', t: [6] }),
  (C) => { const a = Math.sqrt(25); C.assert(near(simpson((x) => 2 * x, 0, a), 25), 'a = 5'); C.blank(a); });

// =============================================================== numerical
Q('n01', mk.num({ stem: r`Evaluate $\displaystyle\int_1^4 (2x + 3)\,dx$.`, value: 24, sol: r`$\left[x^2 + 3x\right]_1^4 = (16 + 12) - (1 + 3) = 24$.`, scheme: [['24', 1]], d: 1, c: 'understanding', t: [6], time: 60 }),
  (C) => C.val(simpson((x) => 2 * x + 3, 1, 4), 1e-6));
Q('n02', mk.num({ stem: r`Evaluate $\displaystyle\int_0^{\pi} |\cos x|\,dx$.`, value: 2, sol: r`$\cos x \ge 0$ on $\left[0, \dfrac{\pi}{2}\right]$ and $\le 0$ on $\left[\dfrac{\pi}{2}, \pi\right]$: the integral is $\left[\sin x\right]_0^{\pi/2} - \left[\sin x\right]_{\pi/2}^{\pi} = 1 + 1 = 2$.`, scheme: [['2', 1]], d: 3, c: 'application', t: [6], time: 90 }),
  (C) => C.val(simpson((x) => abs(cos(x)), 0, P), 1e-6));
Q('n03', mk.num({ stem: r`Evaluate $\displaystyle\int_0^{\log 3} e^x\,dx$.`, value: 2, sol: r`$\left[e^x\right]_0^{\log 3} = 3 - 1 = 2$.`, scheme: [['2', 1]], d: 2, c: 'understanding', t: [6], time: 60 }),
  (C) => C.val(simpson(exp, 0, ln(3)), 1e-6));
Q('n04', mk.num({ stem: r`Evaluate $\displaystyle\int_0^{4} |x - 1|\,dx$.`, value: 5, sol: r`Split at $x = 1$: $\displaystyle\int_0^1 (1 - x)\,dx + \int_1^4 (x - 1)\,dx = \dfrac12 + \dfrac92 = 5$.`, scheme: [['5', 1]], d: 3, c: 'application', t: [6], time: 90 }),
  (C) => C.val(simpson((x) => abs(x - 1), 0, 4, 40000), 1e-6));
Q('n05', mk.num({ stem: r`Using the odd and even parts of the integrand, evaluate $\displaystyle\int_{-2}^{2} (x^3 + 3x^2)\,dx$.`, value: 16, sol: r`$x^3$ is odd and contributes $0$; $3x^2$ is even and gives $2\displaystyle\int_0^2 3x^2\,dx = 2 \times 8 = 16$.`, scheme: [['16', 1]], d: 3, c: 'application', t: [6], time: 75 }),
  (C) => C.val(simpson((x) => x ** 3 + 3 * x * x, -2, 2), 1e-6));
Q('n06', mk.num({ stem: r`Evaluate $\displaystyle\int_0^{1} x e^x\,dx$.`, value: 1, sol: r`By parts, an antiderivative is $(x - 1)e^x$: $\left[(x - 1)e^x\right]_0^1 = 0 - (-1) = 1$.`, scheme: [['1', 1]], d: 3, c: 'application', t: [5, 6], time: 90 }),
  (C) => C.val(simpson((x) => x * exp(x), 0, 1), 1e-6));

// =============================================================== short answer, 2 marks
Q('s201', mk.short({ marks: 2, stem: r`Find $\displaystyle\int \left(\sqrt{x} + \dfrac{1}{\sqrt{x}}\right)^2 dx$, $x > 0$.`, model: r`Expand: $\left(\sqrt{x} + \dfrac{1}{\sqrt{x}}\right)^2 = x + 2 + \dfrac1x$. So the integral is $\dfrac{x^2}{2} + 2x + \log|x| + C$.`, sol: 'Expand the square first, then integrate term by term.', scheme: [['Expansion x + 2 + 1/x', 1], ['x²/2 + 2x + log|x| + C', 1]], d: 2, c: 'understanding', t: [1], time: 120 }),
  (C) => { C.assert(isAnti((x) => x * x / 2 + 2 * x + ln(x), (x) => (sqrt(x) + 1 / sqrt(x)) ** 2, X1), 'antiderivative'); C.model([r`\log|x|`]); });
Q('s202', mk.short({ marks: 2, stem: r`Find $\displaystyle\int \sin^2 x\,dx$.`, model: r`Use $\sin^2 x = \dfrac{1 - \cos 2x}{2}$. Then $\displaystyle\int \sin^2 x\,dx = \dfrac{x}{2} - \dfrac{\sin 2x}{4} + C$.`, sol: 'Lower the power with the double-angle identity.', scheme: [['Identity for sin²x', 1], ['x/2 − sin 2x/4 + C', 1]], d: 2, c: 'understanding', t: [2], time: 120 }),
  (C) => { C.assert(isAnti((x) => x / 2 - sin(2 * x) / 4, (x) => sin(x) ** 2, X1), 'antiderivative'); C.model([r`\dfrac{\sin 2x}{4}`]); });
Q('s203', mk.short({ marks: 2, stem: r`Find $\displaystyle\int \dfrac{\sec^2(\log x)}{x}\,dx$, $x > 0$.`, model: r`Put $t = \log x$, so $dt = \dfrac{dx}{x}$. The integral becomes $\displaystyle\int \sec^2 t\,dt = \tan t + C = \tan(\log x) + C$.`, sol: 'Spot the derivative of the inner function, 1/x, as a factor.', scheme: [['Substitution t = log x with dt', 1], ['tan(log x) + C', 1]], d: 3, c: 'application', t: [2], time: 120 }),
  (C) => { C.assert(isAnti((x) => tan(ln(x)), (x) => sec(ln(x)) ** 2 / x, [1.2, 2, 3]), 'antiderivative'); C.model([r`\tan(\log x)`]); });
Q('s204', mk.short({ marks: 2, stem: r`Find $\displaystyle\int \dfrac{dx}{\sqrt{x^2 - 6x + 13}}$.`, model: r`$x^2 - 6x + 13 = (x - 3)^2 + 2^2$. With the standard form for $\dfrac{1}{\sqrt{u^2 + a^2}}$, the integral is $\log\left|x - 3 + \sqrt{x^2 - 6x + 13}\right| + C$.`, sol: 'Complete the square under the root.', scheme: [['Completing the square', 1], ['Correct log form', 1]], d: 3, c: 'application', t: [3], time: 150 }),
  (C) => { C.assert(isAnti((x) => ln(abs(x - 3 + sqrt(x * x - 6 * x + 13))), (x) => 1 / sqrt(x * x - 6 * x + 13), [-1, 2, 5]), 'antiderivative'); C.model([r`(x - 3)^2 + 2^2`]); });
Q('s205', mk.short({ marks: 2, stem: r`Integrate $\dfrac{1}{(x + 1)(x + 3)}$ with respect to $x$.`, model: r`$\dfrac{1}{(x + 1)(x + 3)} = \dfrac12\left(\dfrac{1}{x + 1} - \dfrac{1}{x + 3}\right)$. Hence the integral is $\dfrac12\log\left|\dfrac{x + 1}{x + 3}\right| + C$.`, sol: 'Split into partial fractions, then use the log rule.', scheme: [['Partial fractions', 1], ['½ log|(x + 1)/(x + 3)| + C', 1]], d: 2, c: 'understanding', t: [4], time: 120 }),
  (C) => { C.assert(same((x) => 1 / ((x + 1) * (x + 3)), (x) => 0.5 * (1 / (x + 1) - 1 / (x + 3)), [0, 2, 7]), 'split'); C.assert(isAnti((x) => 0.5 * ln(abs((x + 1) / (x + 3))), (x) => 1 / ((x + 1) * (x + 3)), [0, 2, 7]), 'antiderivative'); C.model([r`\dfrac12\log`]); });
Q('s206', mk.short({ marks: 2, stem: r`Use integration by parts to find $\displaystyle\int x\cos x\,dx$.`, model: r`Take $u = x$, $dv = \cos x\,dx$, so $du = dx$, $v = \sin x$. Then $\displaystyle\int x\cos x\,dx = x\sin x - \int \sin x\,dx = x\sin x + \cos x + C$.`, sol: 'Let the algebraic factor be u.', scheme: [['Correct choice of u and v', 1], ['x sin x + cos x + C', 1]], d: 2, c: 'understanding', t: [5], time: 120 }),
  (C) => { C.assert(isAnti((x) => x * sin(x) + cos(x), (x) => x * cos(x), X1), 'antiderivative'); C.model([r`x\sin x + \cos x`]); });
Q('s207', mk.short({ marks: 2, stem: r`Evaluate $\displaystyle\int_0^{\pi/2} \cos^2 x\,dx$.`, model: r`$\cos^2 x = \dfrac{1 + \cos 2x}{2}$. So the integral is $\left[\dfrac x2 + \dfrac{\sin 2x}{4}\right]_0^{\pi/2} = \dfrac{\pi}{4} + 0 - 0 = \dfrac{\pi}{4}$.`, sol: 'Use the double-angle identity before integrating.', scheme: [['Identity and antiderivative', 1], ['π/4', 1]], d: 2, c: 'understanding', t: [6], time: 120 }),
  (C) => { C.assert(near(simpson((x) => cos(x) ** 2, 0, P / 2), P / 4), 'π/4'); C.model([r`\dfrac{\pi}{4}`]); });
Q('s208', mk.short({ marks: 2, stem: r`Use the property $\displaystyle\int_0^a f(x)\,dx = \int_0^a f(a - x)\,dx$ to evaluate $\displaystyle\int_0^2 x(2 - x)^5\,dx$.`, model: r`Replace $x$ by $2 - x$: the integral equals $\displaystyle\int_0^2 (2 - x)x^5\,dx = \left[\dfrac{2x^6}{6} - \dfrac{x^7}{7}\right]_0^2 = \dfrac{64}{3} - \dfrac{128}{7} = \dfrac{64}{21}$.`, sol: 'The property moves the fifth power onto a single x.', scheme: [['Property applied correctly', 1], ['64/21', 1]], d: 3, c: 'application', t: [6], time: 150 }),
  (C) => { C.assert(near(simpson((x) => x * (2 - x) ** 5, 0, 2), 64 / 21), '64/21'); C.model([r`\dfrac{64}{21}`]); });
Q('s209', mk.short({ marks: 2, stem: r`The gradient of a curve at any point is $3x^2 + 2x$, and the curve passes through $(1, 5)$. Find its equation and the value of $y$ at $x = 2$.`, model: r`$y = \displaystyle\int (3x^2 + 2x)\,dx = x^3 + x^2 + C$. At $(1, 5)$: $5 = 2 + C$, so $C = 3$ and $y = x^3 + x^2 + 3$. At $x = 2$: $y = 8 + 4 + 3 = 15$.`, sol: 'Integrate, then fix the constant with the given point.', scheme: [['y = x³ + x² + 3', 1], ['y(2) = 15', 1]], d: 2, c: 'application', t: [1], time: 120 }),
  (C) => { const F = (x) => x ** 3 + x * x + 3; C.assert(isAnti(F, (x) => 3 * x * x + 2 * x, X1) && F(1) === 5, 'curve'); C.model([15, 'x^3 + x^2 + 3']); });

// =============================================================== short answer, 3 marks
Q('s301', mk.short({ marks: 3, stem: r`Find $\displaystyle\int \sin^3 x\,dx$.`, model: r`$\sin^3 x = \sin x\,(1 - \cos^2 x)$. Put $t = \cos x$, $dt = -\sin x\,dx$: $\displaystyle\int \sin^3 x\,dx = -\int (1 - t^2)\,dt = -t + \dfrac{t^3}{3} + C = -\cos x + \dfrac{\cos^3 x}{3} + C$.`, sol: 'Keep one sin x for dt and convert the rest to cosines.', scheme: [['sin³x = sin x (1 − cos²x)', 1], ['Substitution t = cos x', 1], ['−cos x + cos³x/3 + C', 1]], d: 3, c: 'application', t: [2], time: 180 }),
  (C) => { C.assert(isAnti((x) => -cos(x) + cos(x) ** 3 / 3, (x) => sin(x) ** 3, X1), 'antiderivative'); C.model([r`\dfrac{\cos^3 x}{3}`]); });
Q('s302', mk.short({ marks: 3, stem: r`Find $\displaystyle\int \dfrac{2x + 5}{x^2 + 4x + 8}\,dx$.`, model: r`The derivative of $x^2 + 4x + 8$ is $2x + 4$, so write $2x + 5 = (2x + 4) + 1$.\n\n$\displaystyle\int \dfrac{2x + 4}{x^2 + 4x + 8}\,dx = \log(x^2 + 4x + 8)$.\n\n$\displaystyle\int \dfrac{dx}{(x + 2)^2 + 2^2} = \dfrac12\tan^{-1}\dfrac{x + 2}{2}$.\n\nAnswer: $\log(x^2 + 4x + 8) + \dfrac12\tan^{-1}\dfrac{x + 2}{2} + C$.`, sol: 'Numerator = derivative of the denominator plus a constant.', scheme: [['Split 2x + 5 = (2x + 4) + 1', 1], ['Log part', 1], ['Inverse tangent part', 1]], d: 3, c: 'application', t: [3], time: 210 }),
  (C) => { C.assert(isAnti((x) => ln(x * x + 4 * x + 8) + atan((x + 2) / 2) / 2, (x) => (2 * x + 5) / (x * x + 4 * x + 8), [-3, 0, 2]), 'antiderivative'); C.model([r`\dfrac12\tan^{-1}\dfrac{x + 2}{2}`]); });
Q('s303', mk.short({ marks: 3, stem: r`Resolve $\dfrac{3x + 1}{(x - 1)^2(x + 3)}$ into partial fractions and hence integrate it.`, model: r`Write $\dfrac{3x + 1}{(x - 1)^2(x + 3)} = \dfrac{A}{x - 1} + \dfrac{B}{(x - 1)^2} + \dfrac{C}{x + 3}$, so $3x + 1 = A(x - 1)(x + 3) + B(x + 3) + C(x - 1)^2$.\n\n$x = 1$: $4 = 4B$, $B = 1$. $x = -3$: $-8 = 16C$, $C = -\dfrac12$. Coefficient of $x^2$: $A + C = 0$, $A = \dfrac12$.\n\nIntegral: $\dfrac12\log|x - 1| - \dfrac{1}{x - 1} - \dfrac12\log|x + 3| + C_1 = \dfrac12\log\left|\dfrac{x - 1}{x + 3}\right| - \dfrac{1}{x - 1} + C_1$.`, sol: 'A repeated linear factor needs two fractions.', scheme: [['Correct form with (x − 1) and (x − 1)²', 1], ['A = 1/2, B = 1, C = −1/2', 1], ['Integral', 1]], d: 4, c: 'application', t: [4], time: 240 }),
  (C) => { const A = 0.5, B = 1, Cc = -0.5; const g = (x) => (3 * x + 1) / ((x - 1) ** 2 * (x + 3)); C.assert(same(g, (x) => A / (x - 1) + B / (x - 1) ** 2 + Cc / (x + 3), [0, 2, 4.5]), 'split'); C.assert(isAnti((x) => 0.5 * ln(abs((x - 1) / (x + 3))) - 1 / (x - 1), g, [0, 2, 4.5]), 'antiderivative'); C.model(['B = 1', r`C = -\dfrac12`, r`A = \dfrac12`]); });
Q('s304', mk.short({ marks: 3, stem: r`Find $\displaystyle\int x^2 e^x\,dx$.`, model: r`By parts with $u = x^2$: $\displaystyle\int x^2e^x\,dx = x^2e^x - \int 2xe^x\,dx$.\n\nAgain with $u = 2x$: $\displaystyle\int 2xe^x\,dx = 2xe^x - 2e^x$.\n\nSo $\displaystyle\int x^2e^x\,dx = e^x(x^2 - 2x + 2) + C$.`, sol: 'Integrate by parts twice, lowering the power of x each time.', scheme: [['First integration by parts', 1], ['Second integration by parts', 1], ['eˣ(x² − 2x + 2) + C', 1]], d: 3, c: 'application', t: [5], time: 210 }),
  (C) => { C.assert(isAnti((x) => exp(x) * (x * x - 2 * x + 2), (x) => x * x * exp(x), X1), 'antiderivative'); C.model(['x^2 - 2x + 2']); });
Q('s305', mk.short({ marks: 3, stem: r`Write the standard result for $\displaystyle\int \sqrt{a^2 - x^2}\,dx$ and use it to find $\displaystyle\int \sqrt{16 - x^2}\,dx$.`, model: r`$\displaystyle\int \sqrt{a^2 - x^2}\,dx = \dfrac x2\sqrt{a^2 - x^2} + \dfrac{a^2}{2}\sin^{-1}\dfrac xa + C$.\n\nWith $a = 4$: $\displaystyle\int \sqrt{16 - x^2}\,dx = \dfrac x2\sqrt{16 - x^2} + 8\sin^{-1}\dfrac x4 + C$.`, sol: 'Here a² = 16, so a²/2 = 8.', scheme: [['Standard result', 1], ['a = 4 identified', 1], ['Final answer', 1]], d: 2, c: 'understanding', t: [5], time: 150 }),
  (C) => { C.assert(isAnti((x) => (x / 2) * sqrt(16 - x * x) + 8 * asin(x / 4), (x) => sqrt(16 - x * x), [-3, 0.5, 3.5]), 'antiderivative'); C.model([r`8\sin^{-1}\dfrac x4`]); });
Q('s306', mk.short({ marks: 3, stem: r`Evaluate $\displaystyle\int_0^{\pi} x\sin x\,dx$.`, model: r`By parts with $u = x$, $dv = \sin x\,dx$: an antiderivative is $-x\cos x + \sin x$.\n\n$\left[-x\cos x + \sin x\right]_0^{\pi} = (-\pi \cdot (-1) + 0) - (0 + 0) = \pi$.`, sol: 'Antiderivative by parts, then apply the limits.', scheme: [['Antiderivative by parts', 2], ['Value π', 1]], d: 3, c: 'application', t: [5, 6], time: 180 }),
  (C) => { C.assert(near(simpson((x) => x * sin(x), 0, P), P), 'π'); C.assert(isAnti((x) => -x * cos(x) + sin(x), (x) => x * sin(x), X1), 'antiderivative'); C.model([r`= \pi`]); });
Q('s307', mk.short({ marks: 3, stem: r`Show that $\displaystyle\int_2^5 \dfrac{\sqrt{x}}{\sqrt{x} + \sqrt{7 - x}}\,dx = \dfrac32$.`, model: r`Let $I$ be the integral. Using $\displaystyle\int_a^b f(x)\,dx = \int_a^b f(a + b - x)\,dx$ with $a + b = 7$:\n\n$I = \displaystyle\int_2^5 \dfrac{\sqrt{7 - x}}{\sqrt{7 - x} + \sqrt{x}}\,dx$.\n\nAdding the two forms, $2I = \displaystyle\int_2^5 1\,dx = 3$, so $I = \dfrac32$.`, sol: 'Replace x by a + b − x and add the two expressions for I.', scheme: [['Property with a + b − x', 1], ['Adding to get 2I = 3', 1], ['I = 3/2', 1]], d: 4, c: 'analysis', t: [6], time: 210 }),
  (C) => { C.assert(near(simpson((x) => sqrt(x) / (sqrt(x) + sqrt(7 - x)), 2, 5), 1.5), '3/2'); C.model([r`\dfrac32`, '2I']); });
Q('s308', mk.short({ marks: 3, stem: r`Find $\displaystyle\int \dfrac{dx}{1 + e^{-x}}$.`, model: r`Multiply numerator and denominator by $e^x$: $\dfrac{1}{1 + e^{-x}} = \dfrac{e^x}{e^x + 1}$.\n\nPut $t = e^x + 1$, $dt = e^x\,dx$: $\displaystyle\int \dfrac{dt}{t} = \log|t| + C$.\n\nAnswer: $\log(1 + e^x) + C$.`, sol: 'Clear the negative exponent first; the numerator becomes the derivative of the denominator.', scheme: [['Rewrite as eˣ/(eˣ + 1)', 1], ['Substitution', 1], ['log(1 + eˣ) + C', 1]], d: 3, c: 'application', t: [2], time: 180 }),
  (C) => { C.assert(isAnti((x) => ln(1 + exp(x)), (x) => 1 / (1 + exp(-x)), [-1, 0.5, 2]), 'antiderivative'); C.model([r`\log(1 + e^x)`]); });

// =============================================================== long answer, 5 marks
Q('l01', mk.long({ stem: r`Find $\displaystyle\int \dfrac{3x - 2}{\sqrt{x^2 + 2x + 5}}\,dx$.`, model: r`**Step 1 (split the numerator).** $\dfrac{d}{dx}(x^2 + 2x + 5) = 2x + 2$. Write $3x - 2 = \dfrac32(2x + 2) - 5$.\n\n**Step 2 (first part).** $\dfrac32\displaystyle\int \dfrac{2x + 2}{\sqrt{x^2 + 2x + 5}}\,dx$: with $t = x^2 + 2x + 5$ this is $\dfrac32 \cdot 2\sqrt{t} = 3\sqrt{x^2 + 2x + 5}$.\n\n**Step 3 (complete the square).** $x^2 + 2x + 5 = (x + 1)^2 + 2^2$.\n\n**Step 4 (second part).** $5\displaystyle\int \dfrac{dx}{\sqrt{(x + 1)^2 + 2^2}} = 5\log\left|x + 1 + \sqrt{x^2 + 2x + 5}\right|$.\n\n**Answer.** $3\sqrt{x^2 + 2x + 5} - 5\log\left|x + 1 + \sqrt{x^2 + 2x + 5}\right| + C$.`, sol: 'Linear over the square root of a quadratic: split into derivative-of-quadratic plus constant.', scheme: [['3x − 2 = (3/2)(2x + 2) − 5', 1], ['First integral 3√(x² + 2x + 5)', 1], ['Completing the square', 1], ['Second integral (log form)', 1], ['Final answer with C', 1]], d: 4, c: 'application', t: [3], time: 420 }),
  (C) => { const q = (x) => x * x + 2 * x + 5; C.assert(isAnti((x) => 3 * sqrt(q(x)) - 5 * ln(abs(x + 1 + sqrt(q(x)))), (x) => (3 * x - 2) / sqrt(q(x)), [-3, 0, 2.5]), 'antiderivative'); C.model([r`\dfrac32(2x + 2) - 5`, r`3\sqrt{x^2 + 2x + 5}`]); });
Q('l02', mk.long({ stem: r`Find $\displaystyle\int \dfrac{x^2 + 2}{(x + 1)(x^2 + 1)}\,dx$.`, model: r`**Step 1 (form).** $\dfrac{x^2 + 2}{(x + 1)(x^2 + 1)} = \dfrac{A}{x + 1} + \dfrac{Bx + C}{x^2 + 1}$, so $x^2 + 2 = A(x^2 + 1) + (Bx + C)(x + 1)$.\n\n**Step 2 (constants).** $x = -1$: $3 = 2A$, $A = \dfrac32$. Coefficient of $x^2$: $1 = A + B$, $B = -\dfrac12$. Constant term: $2 = A + C$, $C = \dfrac12$.\n\n**Step 3 (integrate).** $\dfrac32\log|x + 1| + \displaystyle\int \dfrac{-\frac12 x + \frac12}{x^2 + 1}\,dx$.\n\n**Step 4.** $-\dfrac12\displaystyle\int \dfrac{x}{x^2 + 1}\,dx = -\dfrac14\log(x^2 + 1)$ and $\dfrac12\displaystyle\int \dfrac{dx}{x^2 + 1} = \dfrac12\tan^{-1}x$.\n\n**Answer.** $\dfrac32\log|x + 1| - \dfrac14\log(x^2 + 1) + \dfrac12\tan^{-1}x + C$.`, sol: 'An irreducible quadratic factor takes a linear numerator Bx + C.', scheme: [['Correct partial-fraction form', 1], ['A = 3/2', 1], ['B = −1/2, C = 1/2', 1], ['Integrals of the parts', 1], ['Final answer', 1]], d: 4, c: 'application', t: [4], time: 480 }),
  (C) => { const g = (x) => (x * x + 2) / ((x + 1) * (x * x + 1)); C.assert(same(g, (x) => 1.5 / (x + 1) + (-0.5 * x + 0.5) / (x * x + 1), [0, 2, 3.5]), 'split'); C.assert(isAnti((x) => 1.5 * ln(abs(x + 1)) - 0.25 * ln(x * x + 1) + 0.5 * atan(x), g, [0, 2, 3.5]), 'antiderivative'); C.model([r`A = \dfrac32`, r`B = -\dfrac12`, r`C = \dfrac12`]); });
Q('l03', mk.long({ stem: r`Find $\displaystyle\int e^{2x}\sin x\,dx$.`, model: r`Let $I = \displaystyle\int e^{2x}\sin x\,dx$.\n\n**Step 1.** Parts with $u = \sin x$, $dv = e^{2x}dx$: $I = \dfrac{e^{2x}}{2}\sin x - \dfrac12\displaystyle\int e^{2x}\cos x\,dx$.\n\n**Step 2.** Parts again with $u = \cos x$: $\displaystyle\int e^{2x}\cos x\,dx = \dfrac{e^{2x}}{2}\cos x + \dfrac12 I$.\n\n**Step 3.** So $I = \dfrac{e^{2x}}{2}\sin x - \dfrac{e^{2x}}{4}\cos x - \dfrac14 I$.\n\n**Step 4.** $\dfrac54 I = \dfrac{e^{2x}}{4}(2\sin x - \cos x)$.\n\n**Answer.** $I = \dfrac{e^{2x}}{5}(2\sin x - \cos x) + C$.`, sol: 'Integrate by parts twice and solve for I.', scheme: [['First integration by parts', 1], ['Second integration by parts', 1], ['Equation in I', 1], ['Solving: (5/4)I = …', 1], ['Final answer', 1]], d: 4, c: 'application', t: [5], time: 420 }),
  (C) => { C.assert(isAnti((x) => (exp(2 * x) / 5) * (2 * sin(x) - cos(x)), (x) => exp(2 * x) * sin(x), X1), 'antiderivative'); C.model([r`\dfrac{e^{2x}}{5}(2\sin x - \cos x)`]); });
Q('l04', mk.long({ stem: r`Evaluate $\displaystyle\int_0^{\pi} x\sin^3 x\,dx$.`, model: r`**Step 1.** Let $I = \displaystyle\int_0^{\pi} x\sin^3 x\,dx$. Using $\displaystyle\int_0^a f(x)\,dx = \int_0^a f(a - x)\,dx$ and $\sin(\pi - x) = \sin x$: $I = \displaystyle\int_0^{\pi} (\pi - x)\sin^3 x\,dx$.\n\n**Step 2.** Adding: $2I = \pi\displaystyle\int_0^{\pi} \sin^3 x\,dx$.\n\n**Step 3.** $\sin^3 x = \sin x(1 - \cos^2 x)$; an antiderivative is $-\cos x + \dfrac{\cos^3 x}{3}$.\n\n**Step 4.** $\left[-\cos x + \dfrac{\cos^3 x}{3}\right]_0^{\pi} = \left(1 - \dfrac13\right) - \left(-1 + \dfrac13\right) = \dfrac43$.\n\n**Answer.** $2I = \dfrac{4\pi}{3}$, so $I = \dfrac{2\pi}{3}$.`, sol: 'Remove the factor x with the a − x property before integrating.', scheme: [['Property with π − x', 1], ['2I = π ∫ sin³x dx', 1], ['Antiderivative of sin³x', 1], ['Value 4/3', 1], ['I = 2π/3', 1]], d: 4, c: 'analysis', t: [6], time: 480 }),
  (C) => { C.assert(near(simpson((x) => x * sin(x) ** 3, 0, P), (2 * P) / 3), '2π/3'); C.assert(near(simpson((x) => sin(x) ** 3, 0, P), 4 / 3), '4/3'); C.model([r`\dfrac{2\pi}{3}`, r`\dfrac43`]); });
Q('l05', mk.long({ stem: r`Evaluate $\displaystyle\int_0^3 |x^2 - 3x + 2|\,dx$.`, model: r`**Step 1 (sign).** $x^2 - 3x + 2 = (x - 1)(x - 2)$: it is $\ge 0$ on $[0, 1]$ and $[2, 3]$, and $\le 0$ on $[1, 2]$.\n\n**Step 2 (antiderivative).** $F(x) = \dfrac{x^3}{3} - \dfrac{3x^2}{2} + 2x$; $F(0) = 0$, $F(1) = \dfrac56$, $F(2) = \dfrac23$, $F(3) = \dfrac32$.\n\n**Step 3.** $\displaystyle\int_0^1 = F(1) - F(0) = \dfrac56$; $\displaystyle\int_1^2 |\cdot| = -(F(2) - F(1)) = \dfrac16$; $\displaystyle\int_2^3 = F(3) - F(2) = \dfrac56$.\n\n**Step 4 (sum).** $\dfrac56 + \dfrac16 + \dfrac56 = \dfrac{11}{6}$.`, sol: 'Split the interval at the zeros 1 and 2 and change the sign on the negative piece.', scheme: [['Zeros 1, 2 and sign of each piece', 1], ['Antiderivative F', 1], ['Pieces 5/6 and 5/6', 1], ['Middle piece 1/6 (sign changed)', 1], ['Total 11/6', 1]], d: 4, c: 'application', t: [6], time: 420 }),
  (C) => { C.assert(near(simpson((x) => abs(x * x - 3 * x + 2), 0, 3, 60000), 11 / 6), '11/6'); C.model([r`\dfrac{11}{6}`, r`\dfrac16`]); });
Q('l06', mk.long({ stem: r`Find $\displaystyle\int \sqrt{x^2 + 4x + 13}\,dx$.`, model: r`**Step 1.** $x^2 + 4x + 13 = (x + 2)^2 + 3^2$.\n\n**Step 2 (standard result).** $\displaystyle\int \sqrt{u^2 + a^2}\,du = \dfrac u2\sqrt{u^2 + a^2} + \dfrac{a^2}{2}\log\left|u + \sqrt{u^2 + a^2}\right| + C$.\n\n**Step 3.** Here $u = x + 2$, $du = dx$ and $a = 3$.\n\n**Step 4.** $\dfrac{a^2}{2} = \dfrac92$.\n\n**Answer.** $\dfrac{x + 2}{2}\sqrt{x^2 + 4x + 13} + \dfrac92\log\left|x + 2 + \sqrt{x^2 + 4x + 13}\right| + C$.`, sol: 'Complete the square, then quote the standard result.', scheme: [['Completing the square', 1], ['Correct standard result', 1], ['u = x + 2, a = 3', 1], ['First term', 1], ['Log term with 9/2', 1]], d: 3, c: 'understanding', t: [5], time: 360 }),
  (C) => { const q = (x) => x * x + 4 * x + 13; C.assert(isAnti((x) => ((x + 2) / 2) * sqrt(q(x)) + 4.5 * ln(abs(x + 2 + sqrt(q(x)))), (x) => sqrt(q(x)), [-4, 0, 3]), 'antiderivative'); C.model([r`\dfrac92`, '(x + 2)^2 + 3^2']); });
Q('l07', mk.long({ stem: r`Evaluate $\displaystyle\int_0^{\pi/2} \dfrac{\sin 2x}{1 + \sin^2 x}\,dx$.`, model: r`**Step 1.** $\sin 2x = 2\sin x\cos x$.\n\n**Step 2 (substitution).** Put $t = 1 + \sin^2 x$, so $dt = 2\sin x\cos x\,dx$.\n\n**Step 3 (limits).** $x = 0 \Rightarrow t = 1$; $x = \dfrac{\pi}{2} \Rightarrow t = 2$.\n\n**Step 4.** The integral becomes $\displaystyle\int_1^2 \dfrac{dt}{t} = \left[\log t\right]_1^2$.\n\n**Answer.** $\log 2 - \log 1 = \log 2$.`, sol: 'Change the limits along with the variable.', scheme: [['sin 2x = 2 sin x cos x', 1], ['Substitution and dt', 1], ['New limits 1 and 2', 1], ['Integral of 1/t', 1], ['log 2', 1]], d: 3, c: 'application', t: [2, 6], time: 360 }),
  (C) => { C.assert(near(simpson((x) => sin(2 * x) / (1 + sin(x) ** 2), 0, P / 2), ln(2)), 'log 2'); C.model([r`\log 2`]); });

// =============================================================== case-based
caseQ('c01', {
  passage: r`A storage tank in a Chennai apartment block holds $200$ litres at $t = 0$. During a test, water is pumped in at the rate $r(t) = 40 + 6t$ litres per minute, where $t$ is the time in minutes. No water is drawn out during the test.`,
  d: 3, c: 'application',
  model: r`(a) Option (a): $V(t) = 200 + 40t + 3t^2$. (b) $700$ litres. (c) (i) $2200$ litres. Or (ii) $t = 5$ minutes.`,
  sol: r`(a) $V(t) = 200 + \displaystyle\int_0^t (40 + 6s)\,ds = 200 + 40t + 3t^2$. (b) $\displaystyle\int_0^{10} (40 + 6t)\,dt = 400 + 300 = 700$. (c) (i) $V(20) = 200 + 800 + 1200 = 2200$. (ii) $40t + 3t^2 = 275$ gives $(3t + 55)(t - 5) = 0$, so $t = 5$.`,
  children: [
    child('a', mk.mcq({ stem: 'The volume of water (in litres) in the tank after t minutes is', opts: [r`$200 + 40t + 3t^2$`, r`$40t + 3t^2$`, r`$200 + 40t + 6t^2$`, r`$206 + 40t$`], key: 'a', sol: 'Integrate the rate and add the starting 200 litres. Option (b) forgets the starting amount; (c) does not halve 6t.', d: 2, c: 'understanding', t: [1], time: 60 })),
    child('b', mk.num({ stem: 'How many litres are pumped in during the first 10 minutes?', value: 700, unit: 'L', sol: r`$\displaystyle\int_0^{10} (40 + 6t)\,dt = \left[40t + 3t^2\right]_0^{10} = 700$.`, scheme: [['700', 1]], d: 2, c: 'understanding', t: [6], time: 60 })),
    child('c', mk.short({ marks: 2, stem: '**(i)** Find the volume of water in the tank after 20 minutes.', model: r`$V(20) = 200 + 40(20) + 3(20)^2 = 200 + 800 + 1200 = 2200$ litres.`, sol: 'Substitute t = 20 in V(t).', scheme: [['Correct V(t) used', 1], ['2200 litres', 1]], d: 2, c: 'application', t: [6], time: 120 }), [
      mk.short({ marks: 2, stem: '**(ii)** After how many minutes has 275 litres of water been pumped in?', model: r`$\displaystyle\int_0^t (40 + 6s)\,ds = 40t + 3t^2 = 275$, so $3t^2 + 40t - 275 = 0$, i.e. $(3t + 55)(t - 5) = 0$. Since $t > 0$, $t = 5$ minutes.`, sol: 'Set the accumulated amount equal to 275 and solve the quadratic.', scheme: [['Equation 3t² + 40t − 275 = 0', 1], ['t = 5 minutes', 1]], d: 3, c: 'application', t: [6], time: 150 }),
    ]),
  ],
}, (C) => { const V = (t) => 200 + 40 * t + 3 * t * t; C.assert(isAnti(V, (t) => 40 + 6 * t, [1, 4]) && V(0) === 200, 'V(t)'); C.child('a').key('a'); C.child('b').val(simpson((t) => 40 + 6 * t, 0, 10), 1e-6); C.child('c').model([V(20)]); C.child('cii').assert(near(simpson((t) => 40 + 6 * t, 0, 5), 275), '275 at t = 5'); C.child('cii').model([5]); });

caseQ('c02', {
  passage: r`A cyclist in Mysuru rolls down a long gentle slope. Her speed $t$ seconds after the start is $v(t) = 2 + 3\sqrt{t}$ metres per second, for $0 \le t \le 16$. The distance travelled is the integral of the speed.`,
  d: 3, c: 'application',
  model: r`(a) Option (a): $s(T) = 2T + 2T^{3/2}$. (b) $24$ m. (c) (i) $48$ m. Or (ii) $10$ m/s.`,
  sol: r`(a) $\displaystyle\int_0^T (2 + 3t^{1/2})\,dt = 2T + 2T^{3/2}$. (b) $s(4) = 8 + 16 = 24$. (c) (i) $s(9) - s(4) = 72 - 24 = 48$. (ii) $\dfrac{s(16)}{16} = \dfrac{160}{16} = 10$.`,
  children: [
    child('a', mk.mcq({ stem: 'The distance s(T) (in metres) covered in the first T seconds is', opts: [r`$2T + 2T^{3/2}$`, r`$2T + 3T^{3/2}$`, r`$2 + \dfrac{3}{2\sqrt{T}}$`, r`$2T + \dfrac92T^{3/2}$`], key: 'a', sol: r`The integral of $3t^{1/2}$ is $3 \cdot \dfrac{t^{3/2}}{3/2} = 2t^{3/2}$. Option (c) is the derivative of the speed.`, d: 2, c: 'understanding', t: [1], time: 60 })),
    child('b', mk.num({ stem: 'Find the distance covered in the first 4 seconds.', value: 24, unit: 'm', sol: r`$s(4) = 2(4) + 2(4)^{3/2} = 8 + 16 = 24$ m.`, scheme: [['24', 1]], d: 2, c: 'understanding', t: [6], time: 60 })),
    child('c', mk.short({ marks: 2, stem: '**(i)** Find the distance covered between t = 4 s and t = 9 s.', model: r`$\displaystyle\int_4^9 v(t)\,dt = s(9) - s(4) = (18 + 54) - 24 = 72 - 24 = 48$ m.`, sol: 'Use the antiderivative at both limits.', scheme: [['s(9) = 72', 1], ['48 m', 1]], d: 3, c: 'application', t: [6], time: 120 }), [
      mk.short({ marks: 2, stem: '**(ii)** Find her average speed over the whole 16 seconds.', model: r`Total distance $s(16) = 32 + 2(64) = 160$ m. Average speed $= \dfrac{160}{16} = 10$ m/s.`, sol: 'Average speed is total distance over total time.', scheme: [['s(16) = 160', 1], ['10 m/s', 1]], d: 3, c: 'application', t: [6], time: 120 }),
    ]),
  ],
}, (C) => { const v = (t) => 2 + 3 * sqrt(t); const s = (T) => 2 * T + 2 * T ** 1.5; C.assert(isAnti(s, v, [1, 4, 9]), 's(T)'); C.child('a').key('a'); C.child('b').val(simpson(v, 0, 4, 200000), 1e-4); C.assert(near(simpson(v, 4, 9), s(9) - s(4)), '4 to 9'); C.child('c').model([s(9) - s(4), s(9)]); C.child('cii').model([s(16) / 16, s(16)]); });

caseQ('c03', {
  passage: r`A hosiery unit in Ludhiana finds that the marginal cost of making sweaters is $MC(x) = 0.06x^2 - 3x + 60$ rupees per sweater when $x$ sweaters are made in a day. The fixed cost (cost when $x = 0$) is ₹$2000$. Total cost $C(x)$ is an antiderivative of $MC(x)$.`,
  d: 3, c: 'application',
  model: r`(a) Option (a): $C(x) = 0.02x^3 - 1.5x^2 + 60x + 2000$. (b) ₹$1750$. (c) (i) ₹$13000$. Or (ii) ₹$4070$.`,
  sol: r`(a) Integrate term by term and use $C(0) = 2000$. (b) $\displaystyle\int_0^{50} MC\,dx = 2500 - 3750 + 3000 = 1750$. (c) (i) $C(100) = 20000 - 15000 + 6000 + 2000 = 13000$. (ii) $C(110) - C(100) = 17070 - 13000 = 4070$.`,
  children: [
    child('a', mk.mcq({ stem: 'The total cost function C(x), in rupees, is', opts: [r`$0.02x^3 - 1.5x^2 + 60x + 2000$`, r`$0.06x^3 - 3x^2 + 60x + 2000$`, r`$0.12x - 3$`, r`$0.02x^3 - 1.5x^2 + 60x$`], key: 'a', sol: 'Integrate each term and add the fixed cost. Option (d) leaves out the fixed cost; (c) is the derivative of MC.', d: 2, c: 'understanding', t: [1], time: 60 })),
    child('b', mk.num({ stem: 'By how many rupees does the cost rise when output goes from 0 to 50 sweaters?', value: 1750, unit: '₹', sol: r`$\displaystyle\int_0^{50} (0.06x^2 - 3x + 60)\,dx = \left[0.02x^3 - 1.5x^2 + 60x\right]_0^{50} = 2500 - 3750 + 3000 = 1750$.`, scheme: [['1750', 1]], d: 3, c: 'application', t: [6], time: 90 })),
    child('c', mk.short({ marks: 2, stem: '**(i)** Find the total cost of making 100 sweaters in a day.', model: r`$C(100) = 0.02(10^6) - 1.5(10^4) + 60(100) + 2000 = 20000 - 15000 + 6000 + 2000 = 13000$ rupees.`, sol: 'Substitute x = 100 into C(x).', scheme: [['Substitution', 1], ['₹13000', 1]], d: 2, c: 'understanding', t: [1], time: 120 }), [
      mk.short({ marks: 2, stem: '**(ii)** Find the extra cost of raising the output from 100 to 110 sweaters a day.', model: r`Extra cost $= \displaystyle\int_{100}^{110} MC(x)\,dx = C(110) - C(100)$. $C(110) = 26620 - 18150 + 6600 + 2000 = 17070$, so the extra cost is $17070 - 13000 = 4070$ rupees.`, sol: 'The extra cost is the definite integral of the marginal cost.', scheme: [['Definite integral set up / C(110) = 17070', 1], ['₹4070', 1]], d: 3, c: 'application', t: [6], time: 150 }),
    ]),
  ],
}, (C) => { const MC = (x) => 0.06 * x * x - 3 * x + 60; const Cf = (x) => 0.02 * x ** 3 - 1.5 * x * x + 60 * x + 2000; C.assert(isAnti(Cf, MC, [10, 40, 90]) && Cf(0) === 2000, 'C(x)'); C.child('a').key('a'); C.child('b').val(simpson(MC, 0, 50), 1e-6); C.child('c').model([R6(Cf(100))]); C.child('cii').model([R6(simpson(MC, 100, 110)), R6(Cf(110))]); });

caseQ('c04', {
  passage: r`An e-rickshaw in Lucknow starts from rest at a signal and stops at the next one. Its speed $t$ seconds after starting is $v(t) = 6t - t^2$ metres per second, for $0 \le t \le 6$.`,
  d: 3, c: 'analysis',
  model: r`(a) Option (a): $s(t) = 3t^2 - \dfrac{t^3}{3}$. (b) $36$ m. (c) (i) $\dfrac{26}{3}$ m. Or (ii) both distances are $18$ m.`,
  sol: r`(a) Integrate $v$ with $s(0) = 0$. (b) $s(6) = 108 - 72 = 36$. (c) (i) $s(3) - s(2) = 18 - \dfrac{28}{3} = \dfrac{26}{3}$. (ii) $v(6 - t) = v(t)$, so both halves give $18$ m.`,
  children: [
    child('a', mk.mcq({ stem: 'The distance s(t) in metres covered in the first t seconds is', opts: [r`$3t^2 - \dfrac{t^3}{3}$`, r`$6 - 2t$`, r`$6t^2 - t^3$`, r`$3t^2 - t^3$`], key: 'a', sol: r`The integral of $6t$ is $3t^2$ and of $t^2$ is $\dfrac{t^3}{3}$. Option (b) is the derivative of $v$.`, d: 2, c: 'understanding', t: [1], time: 60 })),
    child('b', mk.num({ stem: 'Find the distance between the two signals (the distance covered until the rickshaw stops at t = 6).', value: 36, unit: 'm', sol: r`$\displaystyle\int_0^6 (6t - t^2)\,dt = \left[3t^2 - \dfrac{t^3}{3}\right]_0^6 = 108 - 72 = 36$ m.`, scheme: [['36', 1]], d: 2, c: 'understanding', t: [6], time: 60 })),
    child('c', mk.short({ marks: 2, stem: '**(i)** Find the distance covered during the third second, that is, from t = 2 to t = 3.', model: r`$\displaystyle\int_2^3 (6t - t^2)\,dt = s(3) - s(2) = 18 - \left(12 - \dfrac83\right) = 18 - \dfrac{28}{3} = \dfrac{26}{3}$ m.`, sol: 'The third second runs from t = 2 to t = 3, not from 0 to 3.', scheme: [['Limits 2 to 3', 1], ['26/3 m', 1]], d: 3, c: 'application', t: [6], time: 120 }), [
      mk.short({ marks: 2, stem: '**(ii)** Show that the rickshaw covers the same distance in its first 3 seconds as in its last 3 seconds.', model: r`First 3 s: $s(3) = 27 - 9 = 18$ m. Last 3 s: $s(6) - s(3) = 36 - 18 = 18$ m. They are equal; this matches $v(6 - t) = 6(6 - t) - (6 - t)^2 = 6t - t^2 = v(t)$, a symmetric speed graph.`, sol: 'Compare the two definite integrals, or use the symmetry of v about t = 3.', scheme: [['First 3 s: 18 m', 1], ['Last 3 s: 18 m, equal', 1]], d: 3, c: 'analysis', t: [6], time: 150 }),
    ]),
  ],
}, (C) => { const v = (t) => 6 * t - t * t; const s = (t) => 3 * t * t - t ** 3 / 3; C.assert(isAnti(s, v, [1, 2.5, 5]), 's(t)'); C.child('a').key('a'); C.child('b').val(simpson(v, 0, 6), 1e-6); C.child('c').assert(near(simpson(v, 2, 3), 26 / 3), '26/3'); C.child('c').model([r`\dfrac{26}{3}`]); C.child('cii').assert(near(simpson(v, 0, 3), simpson(v, 3, 6)) && near(simpson(v, 0, 3), 18), '18 = 18'); C.child('cii').model([18]); });
